{
  "originalFormula": "E_{C} - E_{F} = 0.16eV",
  "genericFormula": "E_{C} - E_{F} = \Delta E",
  "description": "Esta fórmula representa a diferença de energia entre a banda de condução e o nível de Fermi em um semicondutor. A diferença de energia é crucial para entender como os portadores de carga se comportam em materiais semicondutores e como eles podem ser excitados para conduzir eletricidade.",
  "concepts": [
    "Banda de condução",
    "Nível de Fermi",
    "Diferença de energia",
    "Semicondutores"
  ],
  "symbols": [
    {
      "symbol": "E_{C}",
      "description": "Representa a energia do topo da banda de condução, que é a energia mínima necessária para que um elétron possa se mover livremente e contribuir para a condução elétrica."
    },
    {
      "symbol": "E_{F}",
      "description": "Representa o nível de Fermi, que é o nível de energia mais alto ocupado por elétrons a temperatura zero absoluto. Ele indica a probabilidade de ocupação dos estados eletrônicos em um material."
    },
    {
      "symbol": "0.16eV",
      "description": "Representa um valor específico da diferença de energia entre a banda de condução e o nível de Fermi, medido em electronvolts, que é uma unidade de medida de energia comumente usada em física de semicondutores."
    },
    {
      "symbol": "\\Delta E",
      "description": "Representa a diferença de energia entre dois níveis de energia, neste caso, entre a banda de condução e o nível de Fermi. É uma variável que pode assumir diferentes valores dependendo das condições do material."
    }
  ]
}
